#!/usr/bin/env python3
"""Merged plan of cli-zt2 for the live tree after cache-gc: (1) the generated help-snapshot fixture entry is dropped (regenerated by regen-help after the catalogue edit); (2) the `cache status` replacement keeps the synopsis
`cache status [--tasks]` that cache-gc wrote and lists the flags the subcommand really takes. (3) the first note of the `cache` operation (rewritten by cache-gc) is left as authored, the other five notes are converted. Everything else is the original plan; apply it with `--allow-anchored`."""
import json, os
HERE = os.path.dirname(os.path.abspath(__file__))
C = os.path.dirname(os.path.dirname(HERE))
plan = json.load(open(C + "/cli-zt2-tools/plan.json", encoding="utf8"))
kept, dropped = [], 0
for edit in plan["edits"]:
    if edit["path"].endswith("📖️help/🔣️.json"):
        dropped += 1
        continue
    if edit["path"].endswith("⚙️operations/🔣️catalog.json"):
        hit = 0
        for r in edit["replacements"]:
            if r["old"] == '          "synopsis": "cache status",\n':
                r["old"] = '          "synopsis": "cache status [--tasks]",\n'
                r["new"] = '          "synopsis": "cache status [--tasks]", "flags": ["--area", "--json", "--tasks"],\n'
                hit += 1
        assert hit == 1
        for r in edit["replacements"]:
            if r["old"].startswith('        "status prints a CacheStatus, clear prints a CacheClear;'):
                # cache-gc rewrote the first note (the ledger); the remaining five notes keep the bilingual conversion
                r["old"] = r["old"][r["old"].index('        "Nx: status walks'):]
                r["new"] = r["new"][r["new"].index('        {"en": "Nx: status walks'):]
                hit += 1
        assert hit == 2
    kept.append(edit)
assert dropped == 1
plan["edits"] = kept
json.dump(plan, open(HERE + "/cli-zt2-plan.json", "w", encoding="utf8"), ensure_ascii=False, indent=1)
print("merged cli-zt2 plan: %d edits, %d writes (help fixture dropped)" % (len(kept), len(plan["writes"])))
